 unsigned char malformed_tags[][3]={{0,0,0},{128,0,0},{3,1,2},{129,0,0}};CHECK(ad_tagged_decode(malformed_tags[0],1,decoded,1024,&count)==AD_INVALID);CHECK(ad_tagged_decode(malformed_tags[1],1,decoded,1024,&count)==AD_INVALID);CHECK(ad_tagged_decode(malformed_tags[2],3,decoded,1024,&count)==AD_INCOMPLETE);CHECK(ad_tagged_decode(malformed_tags[3],1,decoded,1024,&count)==AD_INCOMPLETE);
